// ==========================================
// FAST O(1) HASH MAP FOR INSTANT BARCODE LOOKUP
// ==========================================
// Instant nanosecond lookups even with 10,000+ items
final Map<String, Map<String, dynamic>> cosmeticBarcodeMap = {
  for (var item in cosmeticDatabase)
    if ((item['barcode'] ?? '').toString().isNotEmpty)
      item['barcode'].toString().trim().toUpperCase(): item,
};

Map<String, dynamic>? findCosmeticByBarcode(String barcode) {
  final clean = barcode.trim().toUpperCase();
  return cosmeticBarcodeMap[clean];
}

List<Map<String, dynamic>> searchCosmeticsByName(String query, {int limit = 15}) {
  final clean = query.trim().toLowerCase();
  if (clean.isEmpty) return [];
  final terms = clean.split(RegExp(r'\s+')).where((t) => t.isNotEmpty).toList();

  return cosmeticDatabase.where((item) {
    final name = (item['name'] ?? '').toString().toLowerCase();
    final brand = (item['brand'] ?? '').toString().toLowerCase();
    final category = (item['category'] ?? '').toString().toLowerCase();
    final full = "$brand $name $category";
    return terms.every((term) => full.contains(term));
  }).take(limit).toList();
}

